/* Self-contained Contact section styles. */
.contact-section {
  --contact-red: #ff1738;
  --contact-red-soft: #ad0e26;
  --contact-ink: #050506;
  --contact-paper: #f5f3f3;
  --contact-muted: #aaa5a7;
  --contact-line: rgba(255, 23, 56, 0.42);
  --contact-panel: rgba(5, 5, 7, 0.8);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-height: min(100svh, 1080px);
  overflow: hidden;
  color: var(--contact-paper);
  background-color: var(--contact-ink);
  background-image:
    linear-gradient(90deg, rgba(0, 0, 0, 0.46), rgba(0, 0, 0, 0.1) 48%, rgba(0, 0, 0, 0.32)),
    url("data:image/png;base64,");
  background-position: center;
  background-size: cover;
  font-family: "Arial Narrow", "Roboto Condensed", "Helvetica Neue", Arial, sans-serif;
}

.contact-section,
.contact-section * {
  box-sizing: border-box;
}

.contact-noise {
  position: absolute;
  inset: 0;
  z-index: -1;
  opacity: 0.16;
  pointer-events: none;
  background-image: radial-gradient(circle, rgba(255, 255, 255, 0.22) 0 0.6px, transparent 0.8px);
  background-size: 5px 5px;
  mask-image: linear-gradient(to bottom, black, transparent 72%);
}

.contact-frame {
  position: absolute;
  inset: clamp(14px, 2vw, 34px);
  z-index: -1;
  border: 1px solid rgba(255, 23, 56, 0.18);
  pointer-events: none;
}

.contact-frame::before,
.contact-frame::after {
  content: "";
  position: absolute;
  width: 54px;
  height: 3px;
  background: var(--contact-red);
  box-shadow: 0 0 16px rgba(255, 23, 56, 0.75);
}

.contact-frame::before { top: -1px; left: 7%; }
.contact-frame::after { right: 7%; bottom: -1px; }

.contact-frame__corner {
  position: absolute;
  width: 30px;
  height: 30px;
  border-color: var(--contact-red);
  border-style: solid;
}

.contact-frame__corner--top {
  top: -1px;
  right: -1px;
  border-width: 1px 1px 0 0;
}

.contact-frame__corner--bottom {
  bottom: -1px;
  left: -1px;
  border-width: 0 0 1px 1px;
}

.contact-shell {
  width: min(100% - clamp(40px, 8vw, 150px), 1500px);
  min-height: min(100svh, 1080px);
  margin-inline: auto;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  padding-top: clamp(42px, 7vh, 90px);
}

.contact-main {
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(390px, 0.82fr);
  align-items: center;
  gap: clamp(50px, 8vw, 145px);
  padding: 0 clamp(6px, 1vw, 18px) clamp(30px, 5vh, 64px);
}

.contact-copy { max-width: 650px; }

.contact-kicker {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-bottom: 14px;
  color: var(--contact-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.contact-kicker strong {
  color: var(--contact-red);
  font-size: clamp(34px, 3vw, 52px);
  line-height: 0.8;
  letter-spacing: 0;
}

.contact-kicker i {
  width: 34px;
  height: 1px;
  margin-left: 8px;
  background: var(--contact-red);
}

.contact-title {
  max-width: 620px;
  margin: 0;
  color: var(--contact-paper);
  font-size: clamp(48px, 5vw, 86px);
  font-weight: 900;
  line-height: 0.88;
  letter-spacing: 0;
  text-transform: uppercase;
}

.contact-title em {
  display: block;
  color: var(--contact-red);
  font-style: normal;
  text-shadow: 0 0 28px rgba(255, 23, 56, 0.24);
}

.contact-intro {
  max-width: 540px;
  margin: 20px 0 clamp(24px, 4vh, 40px);
  color: #c5c1c2;
  font-size: clamp(14px, 1.15vw, 18px);
  line-height: 1.65;
}

.contact-links {
  display: grid;
  gap: 10px;
  width: min(100%, 560px);
}

.contact-link {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  align-items: center;
  min-height: 62px;
  padding: 8px 14px 8px 10px;
  color: var(--contact-paper);
  border: 1px solid rgba(255, 23, 56, 0.46);
  border-left-width: 2px;
  border-radius: 3px;
  background: linear-gradient(90deg, rgba(39, 7, 13, 0.82), rgba(5, 5, 7, 0.72));
  box-shadow: inset 0 0 22px rgba(255, 23, 56, 0.035);
  text-decoration: none;
  transition: border-color 180ms ease, background-color 180ms ease, transform 180ms ease;
}

.contact-link:hover,
.contact-link:focus-visible {
  border-color: var(--contact-red);
  background-color: rgba(35, 7, 12, 0.9);
  transform: translateX(4px);
  outline: none;
}

.contact-link__icon {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: var(--contact-red);
  border: 1px solid rgba(255, 23, 56, 0.5);
}

.contact-link__text {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.contact-link__text strong {
  color: #d5d1d2;
  font-size: 9px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.contact-link__text span {
  overflow: hidden;
  color: #f1eeee;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.contact-link__arrow { color: #aaa5a7; }

.contact-form-wrap {
  position: relative;
  width: 100%;
  max-width: 560px;
  justify-self: end;
  padding: clamp(24px, 2.4vw, 38px);
  border: 1px solid rgba(255, 23, 56, 0.55);
  border-radius: 4px;
  background: linear-gradient(145deg, rgba(14, 12, 14, 0.91), rgba(4, 4, 5, 0.84));
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.42), inset 0 0 35px rgba(255, 23, 56, 0.025);
  backdrop-filter: blur(9px);
}

.contact-form-wrap::before,
.contact-form-wrap::after {
  content: "";
  position: absolute;
  width: 23px;
  height: 23px;
  border-color: var(--contact-red);
  border-style: solid;
}

.contact-form-wrap::before {
  top: -2px;
  right: -2px;
  border-width: 2px 2px 0 0;
}

.contact-form-wrap::after {
  bottom: -2px;
  left: -2px;
  border-width: 0 0 2px 2px;
}

.contact-form-heading {
  display: grid;
  grid-template-columns: auto auto minmax(20px, 1fr);
  align-items: center;
  gap: 10px;
  margin-bottom: 24px;
  color: var(--contact-red);
}

.contact-form-heading h2 {
  margin: 0;
  color: var(--contact-paper);
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.contact-form-heading span {
  height: 1px;
  margin-left: 5px;
  background: linear-gradient(90deg, var(--contact-red), transparent);
}

.contact-form { display: grid; }

.contact-form label {
  margin-bottom: 7px;
  color: #b7b1b3;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.contact-form input,
.contact-form textarea {
  width: 100%;
  margin: 0 0 16px;
  padding: 12px 13px;
  color: var(--contact-paper);
  border: 1px solid rgba(255, 255, 255, 0.17);
  border-radius: 3px;
  outline: none;
  background: rgba(16, 16, 19, 0.86);
  font: inherit;
  font-size: 13px;
  transition: border-color 180ms ease, box-shadow 180ms ease;
}

.contact-form input { height: 44px; }

.contact-form textarea {
  min-height: 122px;
  resize: vertical;
  line-height: 1.5;
}

.contact-form input::placeholder,
.contact-form textarea::placeholder { color: #716c6e; }

.contact-form input:focus,
.contact-form textarea:focus {
  border-color: var(--contact-red);
  box-shadow: 0 0 0 3px rgba(255, 23, 56, 0.11);
}

.contact-submit {
  display: flex;
  width: 100%;
  min-height: 48px;
  align-items: center;
  justify-content: center;
  gap: 11px;
  margin-top: 2px;
  color: var(--contact-paper);
  border: 1px solid var(--contact-red);
  border-radius: 3px;
  background: linear-gradient(90deg, rgba(101, 4, 24, 0.72), rgba(30, 5, 11, 0.82));
  box-shadow: inset 0 0 24px rgba(255, 23, 56, 0.08), 0 0 16px rgba(255, 23, 56, 0.08);
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

.contact-submit:hover,
.contact-submit:focus-visible {
  background-color: rgba(255, 23, 56, 0.2);
  box-shadow: inset 0 0 28px rgba(255, 23, 56, 0.14), 0 0 22px rgba(255, 23, 56, 0.15);
  outline: none;
  transform: translateY(-1px);
}

.contact-status {
  min-height: 17px;
  margin: 9px 0 -8px;
  color: #c4bec0;
  font-size: 10px;
  text-align: center;
}

.contact-footer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 28px;
  min-height: 108px;
  padding: 20px 18px;
  border-top: 1px solid rgba(255, 23, 56, 0.48);
  background: linear-gradient(180deg, rgba(1, 1, 2, 0.3), rgba(1, 1, 2, 0.72));
}

.contact-signature { display: grid; gap: 7px; }

.contact-signature strong {
  font-size: 14px;
  letter-spacing: 0.38em;
  text-transform: uppercase;
}

.contact-signature span,
.contact-footer p,
.contact-motto span {
  color: #9f999b;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.contact-motto {
  display: flex;
  align-items: center;
  gap: 13px;
}

.contact-motto i {
  width: 35px;
  height: 1px;
  background: var(--contact-red-soft);
}

.contact-footer p {
  margin: 0;
  justify-self: end;
  text-align: right;
}

.contact-reveal {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 700ms ease, transform 700ms cubic-bezier(0.22, 1, 0.36, 1);
}

.contact-form-wrap.contact-reveal { transition-delay: 120ms; }
.contact-footer.contact-reveal { transition-delay: 220ms; }

.contact-section.is-visible .contact-reveal {
  opacity: 1;
  transform: translateY(0);
}

.contact-section.is-visible .contact-link {
  animation: contact-link-in 480ms both cubic-bezier(0.22, 1, 0.36, 1);
  animation-delay: calc(180ms + var(--reveal-index) * 75ms);
}

@keyframes contact-link-in {
  from { opacity: 0; transform: translateX(-12px); }
  to { opacity: 1; transform: translateX(0); }
}

@media (max-width: 1100px) {
  .contact-shell {
    width: min(100% - 44px, 960px);
    padding-top: 48px;
  }

  .contact-main {
    grid-template-columns: minmax(0, 0.9fr) minmax(350px, 1fr);
    gap: 32px;
  }

  .contact-title { font-size: clamp(42px, 5.5vw, 64px); }
  .contact-intro { margin: 15px 0 24px; }
  .contact-form-wrap { padding: 24px; }
}

@media (max-width: 820px) {
  .contact-section { min-height: 100svh; }
  .contact-shell {
    width: min(100% - 36px, 700px);
    min-height: 100svh;
    padding-top: 44px;
  }

  .contact-main {
    grid-template-columns: 1fr;
    align-content: start;
    gap: 30px;
    padding-bottom: 34px;
  }

  .contact-copy,
  .contact-form-wrap { max-width: none; }

  .contact-title em { display: inline; }
  .contact-intro { max-width: 590px; }
  .contact-links { width: 100%; }

  .contact-footer {
    grid-template-columns: 1fr auto;
    min-height: 98px;
  }

  .contact-motto { display: none; }
}

@media (max-width: 600px) {
  .contact-section {
    background-image:
      linear-gradient(180deg, rgba(0, 0, 0, 0.28), rgba(0, 0, 0, 0.08) 48%, rgba(0, 0, 0, 0.55)),
      url("data:image/png;base64,");
    background-position: center top;
    background-size: cover;
  }

  .contact-frame { inset: 9px; }

  .contact-shell {
    width: calc(100% - 32px);
    padding-top: 32px;
  }

  .contact-main {
    gap: 24px;
    padding: 0 0 28px;
  }

  .contact-kicker { margin-bottom: 12px; font-size: 8px; }
  .contact-kicker strong { font-size: 30px; }
  .contact-kicker i { width: 22px; margin-left: 3px; }

  .contact-title {
    max-width: 390px;
    font-size: clamp(37px, 11.4vw, 49px);
    line-height: 0.92;
  }

  .contact-title em { display: block; }

  .contact-intro {
    margin: 14px 0 21px;
    font-size: 13px;
    line-height: 1.55;
  }

  .contact-link {
    grid-template-columns: 42px minmax(0, 1fr) auto;
    min-height: 55px;
  }

  .contact-link__text span { font-size: 10px; }
  .contact-form-wrap { padding: 20px 16px 16px; }
  .contact-form-heading { margin-bottom: 18px; }
  .contact-form-heading h2 { font-size: 14px; }
  .contact-form input { height: 43px; }
  .contact-form textarea { min-height: 112px; }

  .contact-footer {
    grid-template-columns: 1fr;
    gap: 14px;
    min-height: 0;
    padding: 20px 4px 25px;
  }

  .contact-footer p { justify-self: start; text-align: left; }
}

@media (max-width: 390px) {
  .contact-shell { width: calc(100% - 26px); padding-top: 26px; }
  .contact-main { gap: 20px; }
  .contact-title { font-size: 39px; }
  .contact-intro { font-size: 12px; }
  .contact-link { padding-right: 9px; }
  .contact-link__text span { font-size: 9px; }
  .contact-form-wrap { padding: 17px 13px 13px; }
  .contact-form input,
  .contact-form textarea { margin-bottom: 12px; }
}

@media (max-height: 780px) and (min-width: 821px) {
  .contact-shell { padding-top: 28px; }
  .contact-main { padding-bottom: 22px; }
  .contact-kicker { margin-bottom: 10px; }
  .contact-title { font-size: clamp(43px, 4.4vw, 68px); }
  .contact-intro { margin: 12px 0 20px; line-height: 1.5; }
  .contact-link { min-height: 54px; }
  .contact-form-wrap { padding-top: 20px; padding-bottom: 16px; }
  .contact-form-heading { margin-bottom: 16px; }
  .contact-form input { height: 39px; margin-bottom: 11px; }
  .contact-form textarea { min-height: 88px; margin-bottom: 11px; }
  .contact-submit { min-height: 43px; }
  .contact-footer { min-height: 78px; padding-block: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .contact-reveal,
  .contact-link,
  .contact-submit {
    animation: none !important;
    transition: none !important;
  }
}
